===================================================================
--- index.html
+++ index.html
@@ -30,4 +30,71 @@
 </div>
 <div class="modalback" id="welcome"><div class="welcome"><div class="eyebrow">A living world, yours to shape</div><h1>Find your<br/><span>wildlands.</span></h1><p>Gather, craft, build and thrive in a world that changes with the sun. Start with empty hands; make a home worth coming back to.</p><div class="welcomegrid"><div><b>✦ Build anything</b>Break blocks, place them, make a shelter.</div><div><b>☾ Survive the night</b>Slimes roam after sundown. Craft a sword.</div><div><b>⚒ Craft & discover</b>Tools, torches, bridges and more.</div><div><b>♧ Grow your food</b>Harvest berries and plant seeds.</div></div><button class="primary" id="startBtn">ENTER THE WILDLANDS&nbsp; →</button><span class="modalfoot">WASD to move · click to gather · C to craft · auto-saves</span></div></div>
 </div>
 <script>
+'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
+const TW=54,TH=28,UNIT=16,MAP=48;
+const $=id=>document.getElementById(id);
+let W=innerWidth,H=innerHeight,DPR=1,now=0,last=0,frame=0,paused=false,started=false,muted=false;
+const keys=new Set(),touchDirs=new Set();
+const state={player:{x:24,y:24,hp:100,energy:100,face:1},inventory:{wood:0,stone:0,berry:2,seed:1,coal:0,iron:0,plank:0,torch:0},tools:{axe:0,pick:0,sword:0},selected:0,world:[],mobs:[],day:1,time:0.22,resourcesGathered:0,crafts:0,killCount:0,weather:'☀ Mild breeze',weatherTick:0,saveTick:0};
+const ITEMS={wood:['🪵','Wood'],stone:['🪨','Stone'],berry:['🍓','Wild berries'],seed:['🌱','Seeds'],coal:['⚫','Coal'],iron:['🧲','Iron ore'],plank:['🪚','Planks'],torch:['🏮','Torches']};
+const HOTS=[['axe','🪓','Axe'],['pick','⛏️','Pickaxe'],['sword','🗡️','Sword'],['wood','🪵','Wood'],['stone','🪨','Stone'],['plank','🪚','Planks'],['torch','🏮','Torch'],['seed','🌱','Seeds']];
+const RECIPES=[{id:'axe',icon:'🪓',name:'Stone axe',cost:{wood:3,stone:2},desc:'Chop trees twice as fast.'},{id:'pick',icon:'⛏️',name:'Stone pickaxe',cost:{wood:2,stone:3},desc:'Mine ore and stone efficiently.'},{id:'sword',icon:'🗡️',name:'Woodland sword',cost:{wood:3,stone:1},desc:'Defend yourself from night slimes.'},{id:'plank',icon:'🪚',name:'Timber planks ×4',cost:{wood:2},desc:'A sturdy building block.'},{id:'torch',icon:'🏮',name:'Torch ×2',cost:{wood:1,coal:1},desc:'Light the darkness. Slimes avoid it.'},{id:'seed',icon:'🌱',name:'Seed pouch ×3',cost:{berry:2},desc:'Plant on grass; harvest after a day.'}];
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function rand(x,y,s=0){let n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n)}
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}
+addEventListener('resize',resize);resize();
+function tile(x,y){if(x<0||y<0||x>=MAP||y>=MAP)return null;return state.world[y][x]}
+function makeWorld(){state.world=Array.from({length:MAP},(_,y)=>Array.from({length:MAP},(_,x)=>{
+ const n=rand(x,y),wave=Math.sin(x*.31)*.12+Math.cos(y*.27)*.11+Math.sin((x+y)*.16)*.08;
+ const edge=Math.min(x,y,MAP-1-x,MAP-1-y);let kind=(n+wave<.22||edge<1)?'water':(n+wave<.31?'sand':'grass');
+ if(kind==='water'&&edge>3&&rand(x+8,y+12)>.82)kind='sand';
+ let obj=null,age=0;
+ const nearSpawn=Math.hypot(x-24,y-24)<4.4;
+ if(kind==='grass'&&!nearSpawn){let r=rand(x*2+3,y*2+5);
+ if(r>.965)obj={type:'iron',hp:3};else if(r>.94)obj={type:'coal',hp:2};else if(r>.86)obj={type:'rock',hp:2};else if(r>.73)obj={type:'tree',hp:3};else if(r>.68)obj={type:'berrybush',hp:1};else if(r>.63)obj={type:'flower',hp:1};else if(r>.625)obj={type:'stump',hp:1};}
+ return {kind,obj,age,lit:0};
+ }));
+ // Keep a small safe clearing around the spawn.
+ for(let y=21;y<=27;y++)for(let x=21;x<=27;x++){let t=tile(x,y);t.kind='grass';if(Math.hypot(x-24,y-24)>2.7&&rand(x,y,5)>.75)t.obj={type:'flower',hp:1};}
+}
+makeWorld();
+function projection(x,y,z=0){const p=state.player,cx=W/2,cy=H/2;return {x:cx+(x-y)*TW/2-(p.x-p.y)*TW/2,y:cy+(x+y)*TH/2-(p.x+p.y)*TH/2-z*UNIT}}
+function pathRound(x,y){return `${Math.floor(x)},${Math.floor(y)}`}
+function poly(points,fill,stroke=null){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
+function diamond(x,y,fill,stroke){poly([[x,y-TH/2],[x+TW/2,y],[x,y+TH/2],[x-TW/2,y]],fill,stroke)}
+function cube(x,y,z,color,topColor=null){const p=projection(x,y,z),hh=UNIT;
+ poly([[p.x-TW*.37,p.y],[p.x,p.y+TH*.43],[p.x,p.y+TH*.43+hh],[p.x-TW*.37,p.y+hh]],shade(color,-19));
+ poly([[p.x,p.y+TH*.43],[p.x+TW*.37,p.y],[p.x+TW*.37,p.y+hh],[p.x,p.y+TH*.43+hh]],shade(color,-35));
+ diamond(p.x,p.y-hh,topColor||shade(color,22),'#11201930');
+}
+function shade(hex,amt){let c=hex.replace('#','');if(c.length===3)c=c.split('').map(x=>x+x).join('');let n=parseInt(c,16),r=clamp((n>>16)+amt,0,255),g=clamp(((n>>8)&255)+amt,0,255),b=clamp((n&255)+amt,0,255);return `rgb(${r},${g},${b})`}
+function drawGround(x,y,t){let p=projection(x,y);let night=nightLevel();let colors={grass:['#6da75c','#548d52'],sand:['#c9b576','#ad9a5f'],water:['#3d8790','#35747f']};let base=colors[t.kind]||colors.grass;
+ let v=rand(x,y,21)*12-6, col=shade(base[0],v-night*25);diamond(p.x,p.y,col,'#11271d28');
+ if(t.kind==='grass'&&rand(x,y,11)>.70&&!t.obj){ctx.fillStyle=`rgba(210,241,147,${.12+rand(x,y,23)*.12})`;ctx.fillRect(p.x+(rand(x,y,41)-.5)*TW*.55,p.y+(rand(x,y,42)-.5)*TH*.35,2,2)}
+ if(t.kind==='water'){let wave=Math.sin(now*2+x*.8+y*.5)*.11;ctx.strokeStyle=`rgba(182,238,226,${.14+wave})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-8,p.y);ctx.lineTo(p.x+5,p.y-4);ctx.stroke()}
+}
+function drawObject(x,y,o,t){let p=projection(x,y);let bob=Math.sin(now*2.7+x*3+y)*1.2;
+ if(o.type==='tree'){
+   // trunk and airy layered canopy
+   cube(x,y,0,'#805334','#97683d');const top=projection(x,y,2.2);ctx.fillStyle='#2e6447';ctx.beginPath();ctx.ellipse(top.x,top.y-9+bob,19,21,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3f8050';ctx.beginPath();ctx.ellipse(top.x-6,top.y-16+bob,13,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#649354';ctx.beginPath();ctx.ellipse(top.x+5,top.y-18+bob,11,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#92b66c88';ctx.beginPath();ctx.arc(top.x-7,top.y-21+bob,4,0,Math.PI*2);ctx.fill();
+ }else if(o.type==='rock'||o.type==='coal'||o.type==='iron'){
+   let col=o.type==='iron'?'#777d78':o.type==='coal'?'#525a56':'#929c86';cube(x,y,0,col,o.type==='iron'?'#b5a886':o.type==='coal'?'#747c73':'#b0b99a');
+   if(o.type==='coal'||o.type==='iron'){ctx.fillStyle=o.type==='coal'?'#252d2b':'#d19c62';ctx.beginPath();ctx.arc(p.x-4,p.y-7,3,0,Math.PI*2);ctx.arc(p.x+5,p.y-5,2,0,Math.PI*2);ctx.fill()}
+ }else if(o.type==='berrybush'){
+   ctx.fillStyle='#3b7142';ctx.beginPath();ctx.ellipse(p.x,p.y-6+bob,14,9,0,0,Math.PI*2);ctx.fill();for(let i=0;i<4;i++){ctx.fillStyle=i%2?'#dd6774':'#f18b76';ctx.beginPath();ctx.arc(p.x-8+(i%2)*11,p.y-8+(i%3)*3+bob,2.4,0,Math.PI*2);ctx.fill()}
+ }else if(o.type==='flower'){
+   ctx.strokeStyle='#4d7b45';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y+2);ctx.lineTo(p.x,p.y-5);ctx.stroke();ctx.fillStyle=rand(x,y,12)>.5?'#f7d683':'#f3a5a2';ctx.beginPath();ctx.arc(p.x,p.y-7+bob,3,0,Math.PI*2);ctx.fill()
+ }else if(o.type==='stump'){cube(x,y,0,'#865b3b','#b77b46')}
+ else if(o.type==='crop'){
+   const grown=o.grown||0;ctx.strokeStyle='#4c8750';ctx.lineWidth=2;for(let i=0;i<Math.max(1,grown+1);i++){ctx.beginPath();ctx.moveTo(p.x+(i-1)*3,p.y+1);ctx.lineTo(p.x+(i-1)*5-2,p.y-7-grown*2);ctx.stroke();ctx.beginPath();ctx.ellipse(p.x+(i-1)*5-3,p.y-7-grown*2,4,2,-.4,0,Math.PI*2);ctx.fillStyle='#7cb957';ctx.fill()}
+ }
+ if(o.lit){ctx.fillStyle=`rgba(255,201,101,${.12+Math.sin(now*4)*.03})`;ctx.beginPath();ctx.arc(p.x,p.y-25,30,0,Math.PI*2);ctx.fill()}
+}
+function nightLevel(){let t=state.time;return clamp((t<.22||t>.78)?(t<.22?(.22-t)/.11:(t-.78)/.11):0,0,.72)}
+function drawPlayer(){let p=projection(state.player.x,state.player.y);let f=state.player.face;ctx.fillStyle='#1b342c55';ctx.beginPath();ctx.ellipse(p.x,p.y+5,12,6,0,0,Math.PI*2);ctx.fill();
+ // legs / body / head in a tiny cozy adventurer style
+ ctx.fillStyle='#334a48';ctx.fillRect(p.x-7,p.y-13,6,13);ctx.fillRect(p.x+1,p.y-13,6,13);ctx.fillStyle='#c37f51';ctx.fillRect(p.x-9,p.y-31,18,19);ctx.fillStyle='#3f7770';ctx.fillRect(p.x-8,p.y-30,16,12);ctx.fillStyle='#e3b982';ctx.beginPath();ctx.arc(p.x,p.y-37,8.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#563d31';ctx.fillRect(p.x-8,p.y-43,16,5);ctx.fillRect(p.x-8+(f<0?-3:5),p.y-38,3,2);
+ const hot=HOTS[state.selected];if(hot&&['axe','pick','sword'].includes(hot[0])){ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(hot[1],p.x+f*14,p.y-21)}
+}

input.oldString:
function drawPlayer(){let p=projection(state.player.x,state.player.y);let f=state.player.face;ctx.fillStyle='#1b342c55';ctx.beginPath();ctx.ellipse(p.x,p.y+5,12,6,0,0,Math.PI*2);ctx.fill();
 // legs / body / head in a tiny cozy adventurer style
 ctx.fillStyle='#334a48';ctx.fillRect(p.x-7,p.y-13,6,13);ctx.fillRect(p.x+1,p.y-13,6,13);ctx.fillStyle='#c37f51';ctx.fillRect(p.x-9,p.y-31,18,19);ctx.fillStyle='#3f7770';ctx.fillRect(p.x-8,p.y-30,16,12);ctx.fillStyle='#e3b982';ctx.beginPath();ctx.arc(p.x,p.y-37,8.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#563d31';ctx.fillRect(p.x-8,p.y-43,16,5);ctx.fillRect(p.x-8+(f<0?-3:5),p.y-38,3,2);
 const hot=HOTS[state.selected];if(hot&&['axe','pick','sword'].includes(hot[0])){ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(hot[1],p.x+f*14,p.y-21)}
}

input.newString:
 const hot=HOTS[state.selected];if(hot&&['axe','pick','sword'].includes(hot[0])){ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(hot[1],p.x+f*14,p.y-21)}
}
function drawMob(m){let p=projection(m.x,m.y);let beat=1+Math.sin(now*5+m.phase)*.08;ctx.fillStyle='#182a2855';ctx.beginPath();ctx.ellipse(p.x,p.y+3,13,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=m.hp<2?'#b7635c':'#83c96d';ctx.beginPath();ctx.ellipse(p.x,p.y-7,12*beat,10/beat,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a6e17d';ctx.beginPath();ctx.ellipse(p.x-3,p.y-10,5,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#24342b';ctx.fillRect(p.x-5,p.y-8,2,3);ctx.fillRect(p.x+3,p.y-8,2,3);if(m.hp<3){ctx.fillStyle='#ffcf69';ctx.fillRect(p.x-11,p.y-22,22,3);ctx.fillStyle='#e96661';ctx.fillRect(p.x-11,p.y-22,22*m.hp/3,3)}}
function pointerTile(px,py){let dx=(px-W/2+((state.player.x-state.player.y)*TW/2))*2/TW,dy=(py-H/2+((state.player.x+state.player.y)*TH/2))*2/TH;return {x:Math.round((dx+dy)/2),y:Math.round((dy-dx)/2)}}
let mouse={x:0,y:0,inside:false},selectedTarget=null;
function render(){ctx.clearRect(0,0,W,H);const p=state.player;let minX=clamp(Math.floor(p.x-24),0,MAP-1),maxX=clamp(Math.ceil(p.x+24),0,MAP-1),minY=clamp(Math.floor(p.y-24),0,MAP-1),maxY=clamp(Math.ceil(p.y+24),0,MAP-1);
 for(let sum=minX+minY;sum<=maxX+maxY;sum++){for(let x=minX;x<=maxX;x++){let y=sum-x;if(y<minY||y>maxY)continue;let t=tile(x,y);if(!t)continue;drawGround(x,y,t);if(t.obj){if(t.obj.type==='crop'&&t.obj.grown<3)t.obj.grown=Math.min(3,Math.floor(t.obj.age/18));drawObject(x,y,t.obj,t)}}
   for(const m of state.mobs)if(Math.floor(m.x)+Math.floor(m.y)===sum)drawMob(m);
   if(Math.floor(p.x)+Math.floor(p.y)===sum)drawPlayer();
 }
 if(mouse.inside){const t=pointerTile(mouse.x,mouse.y),q=projection(t.x,t.y),valid=tile(t.x,t.y);if(valid&&Math.hypot(t.x+.5-p.x,t.y+.5-p.y)<5){ctx.strokeStyle='#e3f4a8cc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y-TH/2);ctx.lineTo(q.x+TW/2,q.y);ctx.lineTo(q.x,q.y+TH/2);ctx.lineTo(q.x-TW/2,q.y);ctx.closePath();ctx.stroke();}}
 // soft vignette and dynamic darkness
 const n=nightLevel();if(n>.02){const g=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.22,W/2,H/2,Math.max(W,H)*.74);g.addColorStop(0,`rgba(17,26,54,${n*.12})`);g.addColorStop(1,`rgba(6,13,34,${n*.7})`);ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
}
function addToast(text,kind=''){const el=document.createElement('div');el.className='toast '+kind;el.textContent=text;$('feed').prepend(el);while($('feed').children.length>4)$('feed').lastChild.remove();setTimeout(()=>el.remove(),3600)}
function setTargetMessage(text){const e=$('tooltip');e.textContent=text;e.classList.add('show');clearTimeout(setTargetMessage.timer);setTargetMessage.timer=setTimeout(()=>e.classList.remove('show'),900)}
function syncVitals(){let p=state.player;$('healthBar').style.width=p.hp+'%';$('energyBar').style.width=p.energy+'%';$('healthNum').textContent=Math.ceil(p.hp);$('energyNum').textContent=Math.ceil(p.energy)}
function syncQuest(){let target=8,done=Math.min(state.resourcesGathered,target),pct=Math.round(done/target*100);$('questProgressText').textContent=`${done} / ${target} resources`;$('questPercent').textContent=pct+'%';$('questBar').style.width=pct+'%';if(done>=target){$('questTitle').textContent='Make yourself at home';$('questText').textContent='You have the basics. Craft a tool, plant a seed, and build a safe place.'}}
function setNight(){let n=nightLevel();$('nightTint').style.opacity=String(n*.32);let t=state.time,mins=Math.floor((t*24*60+480)%1440),hh=Math.floor(mins/60),mm=mins%60;$('clockTime').textContent=String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0');$('phaseText').textContent=t<.18||t>.84?'Quiet night':t<.28?'Dawn light':t<.48?'Bright morning':t<.68?'Golden afternoon':'Blue dusk';$('weatherText').textContent=state.weather;$('dayNum').textContent=state.day}

