function refreshUI(){renderHotbar();renderInventory();renderRecipes();syncVitals();syncQuest()}
function openPanel(id){for(const p of document.querySelectorAll('.panel'))p.classList.remove('open');$(id).classList.add('open')}
function togglePanel(id){$(id).classList.toggle('open')}
function closePanels(){document.querySelectorAll('.panel').forEach(p=>p.classList.remove('open'))}
function dropItem(id,n){state.inventory[id]=(state.inventory[id]||0)+n;return n}
function nearestMob(x,y){let chosen=null,d=999;for(const m of state.mobs){let q=projection(m.x,m.y),dd=Math.hypot(q.x-x,q.y-y);if(dd<d){d=dd;chosen=m}}return d<38?chosen:null}
function getObjectTarget(t){let cell=tile(t.x,t.y);if(cell?.obj)return {cell,obj:cell.obj,x:t.x,y:t.y};let best=null,d=999;for(let y=Math.floor(state.player.y)-4;y<=Math.floor(state.player.y)+4;y++)for(let x=Math.floor(state.player.x)-4;x<=Math.floor(state.player.x)+4;x++){let q=tile(x,y);if(q?.obj){let dd=Math.hypot(x-t.x,y-t.y);if(dd<d){d=dd;best={cell:q,obj:q.obj,x,y}}}}return d<1.2?best:null}
