 if(o.type==='tree'&&state.tools.axe)hit=2;if(['rock','coal','iron'].includes(o.type)&&state.tools.pick)hit=2;
 if(o.type==='crop'){if(o.grown<2){setTargetMessage('Still growing…');return}dropItem('berry',2+Math.floor(Math.random()*2));dropItem('seed',1);target.cell.obj=null;state.resourcesGathered+=1;addToast('Harvested ripe berries + seeds','good');refreshUI();return}
 o.hp=(o.hp||1)-hit;if(o.hp>0){setTargetMessage(`${o.type==='tree'?'Tree':o.type==='berrybush'?'Berry bush':'Rock'} · ${o.hp} hits left`);return}
 let msg='';if(o.type==='tree'){dropItem('wood',3);if(Math.random()<.35)dropItem('seed',1);msg='Tree felled · +3 wood'}else if(o.type==='stump'){dropItem('wood',1);msg='Collected +1 wood'}else if(o.type==='rock'){dropItem('stone',2);msg='Stone gathered · +2 stone'}else if(o.type==='coal'){dropItem('stone',1);dropItem('coal',2);msg='Coal seam mined · +2 coal'}else if(o.type==='iron'){dropItem('stone',1);dropItem('iron',1);msg='Iron ore mined · +1 iron'}else if(o.type==='berrybush'){let n=2+Math.floor(Math.random()*3);dropItem('berry',n);msg=`Wild berries · +${n}`}else if(o.type==='flower'){dropItem('seed',1);msg='Picked a seed · +1 seed'}else if(o.type==='built'){msg='Block reclaimed';dropItem(o.material==='wood'?'wood':o.material==='stone'?'stone':'plank',1)}
 target.cell.obj=null;state.resourcesGathered++;addToast(msg,'good');refreshUI();saveGame()}
function attackMob(m){if(!state.tools.sword){addToast('Craft a sword first to fight back.','warn');return}if(Math.hypot(m.x-state.player.x,m.y-state.player.y)>3.4){setTargetMessage('Move closer to strike');return}m.hp-=2;state.player.face=m.x<state.player.x?-1:1;if(m.hp<=0){state.mobs=state.mobs.filter(x=>x!==m);state.killCount++;dropItem('coal',Math.random()<.45?1:0);if(Math.random()<.55)dropItem('berry',1);addToast('Slime dispersed · it dropped supplies','good');refreshUI()}else addToast('Good hit! The slime is wobbling.','good')}

