function attackMob(m){if(!state.tools.sword){addToast('Craft a sword first to fight back.','warn');return}if(Math.hypot(m.x-state.player.x,m.y-state.player.y)>3.4){setTargetMessage('Move closer to strike');return}m.hp-=2;state.player.face=m.x<state.player.x?-1:1;if(m.hp<=0){state.mobs=state.mobs.filter(x=>x!==m);state.killCount++;dropItem('coal',Math.random()<.45?1:0);if(Math.random()<.55)dropItem('berry',1);addToast('Slime dispersed · it dropped supplies','good');refreshUI()}else addToast('Good hit! The slime is wobbling.','good')}
function isNight(){return state.time<.21||state.time>.79}
function walkable(x,y){let t=tile(Math.floor(x),Math.floor(y));return !!t&&t.kind!=='water'&&(!t.obj||['flower','berrybush','crop'].includes(t.obj.type))}
function movePlayer(dx,dy,dt){let p=state.player;if(!dx&&!dy)return;const len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;let speed=3.1*(keys.has('Shift')&&p.energy>4?1.38:1);let nx=p.x+dx*speed*dt,ny=p.y+dy*speed*dt;if(walkable(nx,p.y))p.x=nx;if(walkable(p.x,ny))p.y=ny;p.face=dx<0?-1:dx>0?1:p.face;p.energy=Math.max(0,p.energy-(keys.has('Shift')?.65:.12)*dt*10)}
function directionInput(){let x=0,y=0;if(keys.has('KeyW')||keys.has('ArrowUp')||touchDirs.has('up'))y--;if(keys.has('KeyS')||keys.has('ArrowDown')||touchDirs.has('down'))y++;if(keys.has('KeyA')||keys.has('ArrowLeft')||touchDirs.has('left'))x--;if(keys.has('KeyD')||keys.has('ArrowRight')||touchDirs.has('right'))x++;return {x,y}}
function placeAt(px,py){if(!started)return;let t=pointerTile(px,py),cell=tile(t.x,t.y),d=Math.hypot(t.x+.5-state.player.x,t.y+.5-state.player.y);if(!cell||d>4.5)return;if(cell.kind==='water'){setTargetMessage('Build on land');return}if(cell.obj){if(cell.obj.type==='crop'&&cell.obj.grown>=2){mineAt(px,py);return}setTargetMessage('That space is occupied');return}let hot=HOTS[state.selected],id=hot?.[0];if(id==='seed'){if(state.inventory.seed<1){setTargetMessage('No seeds in your pack');return}state.inventory.seed--;cell.obj={type:'crop',hp:1,age:0,grown:0};addToast('Seed planted. Give it a day to grow.','good')}else if(id==='torch'){if(state.inventory.torch<1){setTargetMessage('Craft torches at the workbench');return}state.inventory.torch--;cell.obj={type:'torch',hp:1,lit:1};addToast('Torch placed. A little light against the night.','good')}else if(id==='wood'||id==='stone'||id==='plank'){let mat=id==='wood'?'wood':id==='stone'?'stone':'plank';if(state.inventory[id]<1){setTargetMessage(`No ${hot[2].toLowerCase()} to place`);return}state.inventory[id]--;cell.obj={type:'built',material:mat,hp:3};addToast(`${hot[2]} block placed`,'good')}else{setTargetMessage('Select a block, torch or seed to place');return}refreshUI();saveGame()}
function interact(){let best=null,d=999;for(let y=Math.floor(state.player.y)-2;y<=Math.floor(state.player.y)+2;y++)for(let x=Math.floor(state.player.x)-2;x<=Math.floor(state.player.x)+2;x++){let t=tile(x,y);if(t?.obj&&t.obj.type==='crop'){let dd=Math.hypot(x-state.player.x,y-state.player.y);if(dd<d){best={cell:t,x,y};d=dd}}}if(best){if(best.cell.obj.grown>=2){let p=projection(best.x,best.y);mineAt(p.x,p.y)}else addToast('Your crop is growing. Come back after a day.');return}let m=state.mobs.find(m=>Math.hypot(m.x-state.player.x,m.y-state.player.y)<2.3);if(m){attackMob(m);return}togglePanel('inventoryPanel')}
