function loadGame(){try{let data=JSON.parse(localStorage.getItem('wildlandsSave')||'null');if(data){Object.assign(state.player,data.player||{});Object.assign(state.inventory,data.inventory||{});Object.assign(state.tools,data.tools||{});if(data.world?.length===MAP)state.world=data.world;state.day=data.day||1;state.time=data.time||.22;state.resourcesGathered=data.resourcesGathered||0;state.crafts=data.crafts||0;return true}}catch(e){}return false}
function startGame(){if(started)return;let loaded=loadGame();started=true;$('welcome').classList.add('hidden');if(loaded)addToast('Welcome back to your wildlands.','good');else addToast('Gather wood and stone to begin crafting.','good');refreshUI();last=performance.now();requestAnimationFrame(loop)}
$('startBtn').addEventListener('click',startGame);
$('inventoryBtn').onclick=()=>togglePanel('inventoryPanel');$('craftBtn').onclick=()=>togglePanel('craftPanel');$('craftQuick').onclick=()=>togglePanel('craftPanel');
$('saveBtn').onclick=()=>{saveGame();addToast('World saved. See you soon!','good')};
$('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').textContent=muted?'♩':'♫';addToast(muted?'Sound effects muted.':'Sound effects on.','')};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closePanels);
document.addEventListener('click',e=>{if(e.target.id==='eatButton'){if(state.inventory.berry<2){addToast('Need 2 wild berries to eat.','warn');return}state.inventory.berry-=2;state.player.hp=Math.min(100,state.player.hp+18);state.player.energy=Math.min(100,state.player.energy+20);addToast('A tasty snack. Vitality restored.','good');refreshUI()}});
canvas.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;mouse.inside=true});canvas.addEventListener('mouseleave',()=>mouse.inside=false);
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(!started)return;canvas.setPointerCapture?.(e.pointerId);if(e.button===2||e.pointerType==='touch'&&e.shiftKey){placeAt(e.clientX,e.clientY);return}if(e.button===0){mineAt(e.clientX,e.clientY)}});
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code.startsWith('Digit')){let n=Number(e.code.slice(5));if(n>=1&&n<=HOTS.length)selectSlot(n-1)}if(e.code==='KeyI')togglePanel('inventoryPanel');if(e.code==='KeyC')togglePanel('craftPanel');if(e.code==='KeyE')interact();if(e.code==='Escape'){closePanels();paused=!paused;$('pauseBadge').classList.toggle('show',paused)}if(e.code==='Space'){let m=state.mobs.find(m=>Math.hypot(m.x-state.player.x,m.y-state.player.y)<3.5);if(m)attackMob(m)}});
addEventListener('keyup',e=>keys.delete(e.code));
for(const btn of document.querySelectorAll('[data-dir]')){const dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);touchDirs.add(dir)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,()=>touchDirs.delete(dir))}
$('mobileMine').addEventListener('pointerdown',e=>{e.preventDefault();if(!started)return;let m=state.mobs.find(m=>Math.hypot(m.x-state.player.x,m.y-state.player.y)<3.3);if(m)attackMob(m);else{let t=tile(Math.floor(state.player.x+state.player.face),Math.floor(state.player.y));if(t?.obj){let p=projection(Math.floor(state.player.x+state.player.face),Math.floor(state.player.y));mineAt(p.x,p.y)}else interact()}});
$('hotbar').addEventListener('wheel',e=>{e.preventDefault();selectSlot(state.selected+(e.deltaY>0?1:-1))},{passive:false});
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});
// Initial UI and a gentle ambient world preview behind the welcome card.
refreshUI();setNight();render();requestAnimationFrame(function attract(ts){if(!started){now=ts/1000;render();setNight();requestAnimationFrame(attract)}});
</script>
</body>
</html>

